select year(p.launch_date) as launch_year, p.supplier_id, round(avg(ss.units), 2) as avg_units from store_sales ss inner join products p on ss.product_id = p.id full outer join suppliers s on s.id = p.supplier_id where p.supplier_id in (10, 29) group by year(p.launch_date), p.supplier_id having round(avg(ss.units), 2) >= 55 order by avg_units desc, launch_year, supplier_id limit 50;
